mapper.select:
select tcg.id, tcg.group_code, tcg.group_name, tcg.status, tcg.create_time, tcg.update_time, tc.city_name as base_city_name, tcrew.name as leader_name from tb_crew_group tcg left join tb_city tc on tc.id = tcg.base_city_id and tc.is_deleted = 0 left join tb_crew tcrew on tcrew.id = tcg.leader_id and tcrew.is_deleted = 0
and tcg.is_deleted = 0
and tcg.group_name like concat('%', #{groupName}, '%')
and tcg.group_code like concat('%', #{groupCode}, '%')
and tcg.status = #{status}
and tcg.leader_id = #{leaderId}
and tcg.base_city_id = #{baseCityId}
